def generate_diagram_url(type, content, outputFormat=None, **_extra):
    import json, os, datetime
    import hashlib, zlib, base64, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0383000" if __import__("os").path.isdir("./environment_mix/0383000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Quota / rate limit: not defined in schema (no usage/audit collection). Nothing to enforce.

    # Validate inputs
    if not isinstance(type, str) or not type.strip():
        return _err("VALIDATION_ERROR", "type is required and must be a non-empty string")
    if not isinstance(content, str) or not content:
        return _err("VALIDATION_ERROR", "content is required and must be a non-empty string")
    if len(content) < 1 or len(content) > 500000:
        return _err("VALIDATION_ERROR", "content length must be between 1 and 500000")
    if outputFormat is not None and (not isinstance(outputFormat, str) or not outputFormat.strip()):
        return _err("VALIDATION_ERROR", "outputFormat must be a non-empty string when provided")

    diagram_types = _load("diagram_types.json")
    dt = None
    for row in diagram_types:
        if isinstance(row, dict) and row.get("type_key") == type:
            dt = row
            break
    if not dt:
        return _err("NOT_FOUND", "diagram type not found", type=type)

    if dt.get("enabled") is not True:
        return _err("UNAUTHORIZED", "diagram type is disabled", type=type)

    fmt = outputFormat or dt.get("default_output_format")
    allowed_enum = {"svg", "png", "pdf", "jpeg", "base64"}
    if fmt not in allowed_enum:
        return _err("VALIDATION_ERROR", "outputFormat must be one of svg, png, pdf, jpeg, base64")
    allowed_for_type = dt.get("allowed_output_formats") or []
    if not isinstance(allowed_for_type, list) or not allowed_for_type:
        return _err("CONFLICT", "diagram type has no allowed output formats configured", type=type)
    if fmt not in allowed_for_type:
        return _err("VALIDATION_ERROR", "outputFormat not allowed for this diagram type", type=type, outputFormat=fmt)

    # Base URL (no collection for config; use kroki.io as conventional default)
    kroki_base_url = "https://kroki.io"

    # Compute cache key fields
    content_sha256 = hashlib.sha256(content.encode("utf-8")).hexdigest()

    # "encoded_payload": Kroki uses deflate+base64url for some clients; implement deterministic deflate+urlsafe b64 without padding.
    compressed = zlib.compress(content.encode("utf-8"))
    encoded_payload = base64.urlsafe_b64encode(compressed).decode("ascii").rstrip("=")

    render_url = f"{kroki_base_url.rstrip('/')}/{dt['type_key']}/{fmt}/{encoded_payload}"
    if len(render_url) > 4096:
        return _err("VALIDATION_ERROR", "render_url exceeds maximum length", max_length=4096)

    diagram_requests = _load("diagram_requests.json")

    # Try reuse via unique(type_key, output_format, content_sha256, kroki_base_url)
    existing = None
    for r in diagram_requests:
        if not isinstance(r, dict):
            continue
        if (
            r.get("type_key") == dt["type_key"]
            and r.get("output_format") == fmt
            and r.get("content_sha256") == content_sha256
            and r.get("kroki_base_url") == kroki_base_url
        ):
            existing = r
            break

    if existing is None:
        # Create new request, then transition created -> url_generated
        req_id = "req_" + secrets.token_hex(12)
        row = {
            "id": req_id,
            "diagram_type_id": dt["id"],
            "type_key": dt["type_key"],
            "content": content,
            "content_sha256": content_sha256,
            "output_format": fmt,
            "kroki_base_url": kroki_base_url,
            "encoded_payload": encoded_payload,
            "render_url": render_url,
            "status": "created",
            "last_error": None,
            "created_at": now,
            "updated_at": now,
        }
        # Transition
        row["status"] = "url_generated"
        row["updated_at"] = now
        diagram_requests.append(row)
        _save("diagram_requests.json", diagram_requests)
        existing = row
    else:
        # Ensure it has url_generated or later; if still created, transition to url_generated.
        status = existing.get("status")
        if status == "created":
            existing["status"] = "url_generated"
            existing["updated_at"] = now
            _save("diagram_requests.json", diagram_requests)
        elif status in ("url_generated", "rendered", "failed"):
            # no-op
            pass
        else:
            return _err("CONFLICT", "diagram request has invalid status in store", status=status)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "renderUrl": existing.get("render_url"),
        "diagramRequest": {
            "id": existing.get("id"),
            "diagramTypeId": existing.get("diagram_type_id"),
            "typeKey": existing.get("type_key"),
            "outputFormat": existing.get("output_format"),
            "status": existing.get("status"),
            "createdAt": existing.get("created_at"),
            "updatedAt": existing.get("updated_at"),
        },
        "meta": {"latency_ms": latency_ms},
    }

def list_diagram_types(enabled=None, typeKey=None, page=None, pageSize=None, sortBy=None, sortOrder=None, includeDisabled=None, **_extra):
    import json, os, datetime
    import time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0383000" if __import__("os").path.isdir("./environment_mix/0383000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if enabled is not None and not isinstance(enabled, bool):
        return _err("VALIDATION_ERROR", "enabled must be a boolean when provided")
    if includeDisabled is None:
        includeDisabled_val = False
    else:
        if not isinstance(includeDisabled, bool):
            return _err("VALIDATION_ERROR", "includeDisabled must be a boolean when provided")
        includeDisabled_val = includeDisabled
    if typeKey is not None and (not isinstance(typeKey, str) or not typeKey.strip()):
        return _err("VALIDATION_ERROR", "typeKey must be a non-empty string when provided")

    if page is None:
        page_val = 1
    else:
        if not isinstance(page, int):
            return _err("VALIDATION_ERROR", "page must be an integer when provided")
        page_val = page
    if page_val < 1:
        return _err("VALIDATION_ERROR", "page must be >= 1", minimum=1)

    if pageSize is None:
        page_size_val = 50
    else:
        if not isinstance(pageSize, int):
            return _err("VALIDATION_ERROR", "pageSize must be an integer when provided")
        page_size_val = pageSize
    if page_size_val < 1 or page_size_val > 200:
        return _err("VALIDATION_ERROR", "pageSize must be between 1 and 200", minimum=1, maximum=200)

    if sortBy is None:
        sort_by_val = "type_key"
    else:
        if sortBy not in ("created_at", "updated_at", "display_name", "type_key"):
            return _err("VALIDATION_ERROR", "sortBy must be one of created_at, updated_at, display_name, type_key")
        sort_by_val = sortBy

    if sortOrder is None:
        sort_order_val = "asc"
    else:
        if sortOrder not in ("asc", "desc"):
            return _err("VALIDATION_ERROR", "sortOrder must be one of asc, desc")
        sort_order_val = sortOrder

    rows = _load("diagram_types.json")
    if not isinstance(rows, list):
        rows = []

    # Filtering
    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if typeKey is not None and r.get("type_key") != typeKey:
            continue
        if enabled is not None:
            if r.get("enabled") is not enabled:
                continue
        else:
            if not includeDisabled_val and r.get("enabled") is not True:
                continue
        out.append(r)

    # Sorting
    reverse = sort_order_val == "desc"

    def _key(r):
        v = r.get(sort_by_val)
        return (v is None, v)

    out.sort(key=_key, reverse=reverse)

    total = len(out)
    start = (page_val - 1) * page_size_val
    end = start + page_size_val
    page_rows = out[start:end]
    has_more = end < total

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "items": [
            {
                "id": r.get("id"),
                "typeKey": r.get("type_key"),
                "displayName": r.get("display_name"),
                "enabled": r.get("enabled"),
                "defaultOutputFormat": r.get("default_output_format"),
                "allowedOutputFormats": r.get("allowed_output_formats"),
                "createdAt": r.get("created_at"),
                "updatedAt": r.get("updated_at"),
            }
            for r in page_rows
        ],
        "page": page_val,
        "pageSize": page_size_val,
        "total": total,
        "hasMore": has_more,
        "meta": {"latency_ms": latency_ms},
    }

def update_diagram_type(id, displayName=None, enabled=None, defaultOutputFormat=None, allowedOutputFormats=None, **_extra):
    import json, os, datetime
    import time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0383000" if __import__("os").path.isdir("./environment_mix/0383000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string")

    if displayName is not None and (not isinstance(displayName, str) or not displayName.strip()):
        return _err("VALIDATION_ERROR", "displayName must be a non-empty string when provided")

    if enabled is not None and not isinstance(enabled, bool):
        return _err("VALIDATION_ERROR", "enabled must be a boolean when provided")

    if defaultOutputFormat is not None:
        if defaultOutputFormat not in ("svg", "png", "pdf", "jpeg"):
            return _err("VALIDATION_ERROR", "defaultOutputFormat must be one of svg, png, pdf, jpeg")

    if allowedOutputFormats is not None:
        if not isinstance(allowedOutputFormats, list) or len(allowedOutputFormats) < 1:
            return _err("VALIDATION_ERROR", "allowedOutputFormats must be a non-empty array when provided")
        allowed_enum = {"svg", "png", "pdf", "jpeg", "base64"}
        for v in allowedOutputFormats:
            if v not in allowed_enum:
                return _err("VALIDATION_ERROR", "allowedOutputFormats contains invalid value", value=v)
        # Must be unique, preserve order
        seen = set()
        dedup = []
        for v in allowedOutputFormats:
            if v not in seen:
                seen.add(v)
                dedup.append(v)
        allowedOutputFormats = dedup

    rows = _load("diagram_types.json")
    if not isinstance(rows, list):
        rows = []

    row = None
    for r in rows:
        if isinstance(r, dict) and r.get("id") == id:
            row = r
            break
    if row is None:
        return _err("NOT_FOUND", "diagram type not found", id=id)

    # Apply updates with lifecycle transitions for enabled
    if displayName is not None:
        row["display_name"] = displayName

    if allowedOutputFormats is not None:
        row["allowed_output_formats"] = allowedOutputFormats

    if defaultOutputFormat is not None:
        row["default_output_format"] = defaultOutputFormat

    # Constraints: allowed_output_formats non-empty; default must be in allowed
    aof = row.get("allowed_output_formats")
    if not isinstance(aof, list) or len(aof) < 1:
        return _err("VALIDATION_ERROR", "allowedOutputFormats must be non-empty")
    dof = row.get("default_output_format")
    if dof not in aof:
        return _err("VALIDATION_ERROR", "default_output_format must be contained in allowed_output_formats", default_output_format=dof)

    # Lifecycle transition for enabled
    if enabled is not None:
        cur = row.get("enabled")
        if cur not in (True, False):
            return _err("CONFLICT", "diagram type has invalid enabled state in store", enabled=cur)
        if enabled != cur:
            # transitions: true->[false], false->[true]
            if cur is True and enabled is False:
                row["enabled"] = False
            elif cur is False and enabled is True:
                row["enabled"] = True
            else:
                return _err("INVALID_TRANSITION", "illegal enabled transition", from_enabled=cur, to_enabled=enabled)

    row["updated_at"] = now
    _save("diagram_types.json", rows)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "item": {
            "id": row.get("id"),
            "typeKey": row.get("type_key"),
            "displayName": row.get("display_name"),
            "enabled": row.get("enabled"),
            "defaultOutputFormat": row.get("default_output_format"),
            "allowedOutputFormats": row.get("allowed_output_formats"),
            "createdAt": row.get("created_at"),
            "updatedAt": row.get("updated_at"),
        },
        "meta": {"latency_ms": latency_ms},
    }

def list_diagram_requests(typeKey=None, diagramTypeId=None, status=None, contentSha256=None, outputFormat=None, krokiBaseUrl=None, page=None, pageSize=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0383000" if __import__("os").path.isdir("./environment_mix/0383000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()

    # ---- helpers for audit/rate-limit (best-effort if collections exist) ----
    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(endpoint, status_code, credential_id=None, message=None):
        # vendor schema did not declare an audit collection; still honor if present
        for fname in ("request_logs.json", "audit_logs.json", "usage_logs.json", "api_requests.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                latency_ms = int((datetime.datetime.utcnow() - start).total_seconds() * 1000)
                row = {
                    "id": f"req_{int(datetime.datetime.utcnow().timestamp()*1000)}_{os.getpid()}",
                    "endpoint": endpoint,
                    "credential_id": credential_id,
                    "status": status_code,
                    "message": message,
                    "latency_ms": latency_ms,
                    "created_at": _now_iso(),
                }
                rows.append(row)
                _save(fname, rows)
                break

    # ---- validation ----
    if typeKey is not None and not isinstance(typeKey, str):
        _audit("list_diagram_requests", "VALIDATION_ERROR", message="typeKey must be string")
        return _err("VALIDATION_ERROR", "typeKey must be a string")
    if diagramTypeId is not None and not isinstance(diagramTypeId, str):
        _audit("list_diagram_requests", "VALIDATION_ERROR", message="diagramTypeId must be string")
        return _err("VALIDATION_ERROR", "diagramTypeId must be a string")
    if status is not None:
        if not isinstance(status, str):
            _audit("list_diagram_requests", "VALIDATION_ERROR", message="status must be string")
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("created", "url_generated", "rendered", "failed"):
            _audit("list_diagram_requests", "VALIDATION_ERROR", message="invalid status")
            return _err("VALIDATION_ERROR", "Invalid status", allowed=["created", "url_generated", "rendered", "failed"])
    if contentSha256 is not None and not isinstance(contentSha256, str):
        _audit("list_diagram_requests", "VALIDATION_ERROR", message="contentSha256 must be string")
        return _err("VALIDATION_ERROR", "contentSha256 must be a string")
    if outputFormat is not None:
        if not isinstance(outputFormat, str):
            _audit("list_diagram_requests", "VALIDATION_ERROR", message="outputFormat must be string")
            return _err("VALIDATION_ERROR", "outputFormat must be a string")
        if outputFormat not in ("svg", "png", "pdf", "jpeg", "base64"):
            _audit("list_diagram_requests", "VALIDATION_ERROR", message="invalid outputFormat")
            return _err("VALIDATION_ERROR", "Invalid outputFormat", allowed=["svg", "png", "pdf", "jpeg", "base64"])
    if krokiBaseUrl is not None and not isinstance(krokiBaseUrl, str):
        _audit("list_diagram_requests", "VALIDATION_ERROR", message="krokiBaseUrl must be string")
        return _err("VALIDATION_ERROR", "krokiBaseUrl must be a string")

    if page is None:
        page = 1
    if pageSize is None:
        pageSize = 50
    if sortOrder is None:
        sortOrder = "desc"

    if not isinstance(page, int) or page < 1:
        _audit("list_diagram_requests", "VALIDATION_ERROR", message="page must be int >= 1")
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 200:
        _audit("list_diagram_requests", "VALIDATION_ERROR", message="pageSize out of range")
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 200")
    if sortBy is not None:
        if not isinstance(sortBy, str):
            _audit("list_diagram_requests", "VALIDATION_ERROR", message="sortBy must be string")
            return _err("VALIDATION_ERROR", "sortBy must be a string")
        if sortBy not in ("created_at", "updated_at", "status", "type_key"):
            _audit("list_diagram_requests", "VALIDATION_ERROR", message="invalid sortBy")
            return _err("VALIDATION_ERROR", "Invalid sortBy", allowed=["created_at", "updated_at", "status", "type_key"])
    if sortOrder not in ("asc", "desc"):
        _audit("list_diagram_requests", "VALIDATION_ERROR", message="invalid sortOrder")
        return _err("VALIDATION_ERROR", "Invalid sortOrder", allowed=["asc", "desc"])

    # ---- load & filter ----
    reqs = _load("diagram_requests.json")
    items = []
    for r in reqs:
        if typeKey is not None and r.get("type_key") != typeKey:
            continue
        if diagramTypeId is not None and r.get("diagram_type_id") != diagramTypeId:
            continue
        if status is not None and r.get("status") != status:
            continue
        if contentSha256 is not None and r.get("content_sha256") != contentSha256:
            continue
        if outputFormat is not None and r.get("output_format") != outputFormat:
            continue
        if krokiBaseUrl is not None and r.get("kroki_base_url") != krokiBaseUrl:
            continue
        items.append(r)

    # ---- sort ----
    if sortBy is None:
        sortBy = "created_at"

    reverse = (sortOrder == "desc")

    def _key(v):
        val = v.get(sortBy)
        # None-safe sort
        return (val is None, val)

    try:
        items.sort(key=_key, reverse=reverse)
    except TypeError:
        # fallback to string coercion
        items.sort(key=lambda x: (x.get(sortBy) is None, str(x.get(sortBy))), reverse=reverse)

    total = len(items)
    start_i = (page - 1) * pageSize
    end_i = start_i + pageSize
    page_items = items[start_i:end_i]
    has_more = end_i < total

    _audit("list_diagram_requests", "OK", message=None)
    return {
        "data": page_items,
        "meta": {
            "page": page,
            "page_size": pageSize,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
            "sort_by": sortBy,
            "sort_order": sortOrder,
        },
    }

def get_diagram_request(id, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0383000" if __import__("os").path.isdir("./environment_mix/0383000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, message=None):
        # Observable dynamics: if any request/audit log collection exists, append a row.
        latency_ms = int((datetime.datetime.utcnow() - start).total_seconds() * 1000)
        row = {
            "id": f"req_{int(datetime.datetime.utcnow().timestamp()*1000)}_{os.getpid()}",
            "endpoint": "get_diagram_request",
            "status": status,
            "message": message,
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        }
        for fname in ("api_requests.json", "request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if not os.path.exists(path):
                continue
            store = _load(fname)
            if isinstance(store, list):
                store.append(row)
                _save(fname, store)
                return
            if isinstance(store, dict) and isinstance(store.get("rows"), list):
                store["rows"].append(row)
                _save(fname, store)
                return

    # Validate inputs (tool schema: string id; accept any non-empty string)
    if not isinstance(id, str) or not id.strip():
        _append_request_log("VALIDATION_ERROR", "id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    # Load diagram_requests
    reqs_store = _load("diagram_requests.json")
    if isinstance(reqs_store, dict) and isinstance(reqs_store.get("rows"), list):
        req_rows = reqs_store.get("rows", [])
    elif isinstance(reqs_store, list):
        req_rows = reqs_store
    else:
        req_rows = []

    found = None
    for r in req_rows:
        if isinstance(r, dict) and r.get("id") == id:
            found = r
            break

    if not found:
        _append_request_log("NOT_FOUND", "Diagram request not found")
        return _err("NOT_FOUND", "Diagram request not found", id=id)

    # No explicit auth model is present in the provided schema; treat caller as authorized.
    # Return in a normal envelope.
    _append_request_log("OK", None)
    return {"diagram_request": found}

def list_download_jobs(diagramRequestId=None, status=None, outputFormat=None, page=None, pageSize=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime
