    def _audit(endpoint, status_code, credential_id=None, message=None):
        for fname in ("request_logs.json", "audit_logs.json", "usage_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                rows = _load(fname)
                latency_ms = int((datetime.datetime.utcnow() - start).total_seconds() * 1000)
                rows.append({
                    "id": f"req_{int(datetime.datetime.utcnow().timestamp()*1000)}_{os.getpid()}",
                    "endpoint": endpoint,
                    "credential_id": credential_id,
                    "status": status_code,
                    "message": message,
                    "latency_ms": latency_ms,
                    "created_at": _now_iso(),
                })
                _save(fname, rows)
                break

    if diagramRequestId is not None and not isinstance(diagramRequestId, str):
        _audit("list_download_jobs", "VALIDATION_ERROR", message="diagramRequestId must be string")
        return _err("VALIDATION_ERROR", "diagramRequestId must be a string")

    if status is not None:
        if not isinstance(status, str):
            _audit("list_download_jobs", "VALIDATION_ERROR", message="status must be string")
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("queued", "rendering", "writing", "completed", "failed", "cancelled"):
            _audit("list_download_jobs", "VALIDATION_ERROR", message="invalid status")
            return _err("VALIDATION_ERROR", "Invalid status", allowed=["queued", "rendering", "writing", "completed", "failed", "cancelled"])

    if outputFormat is not None:
        if not isinstance(outputFormat, str):
            _audit("list_download_jobs", "VALIDATION_ERROR", message="outputFormat must be string")
            return _err("VALIDATION_ERROR", "outputFormat must be a string")
        if outputFormat not in ("svg", "png", "pdf", "jpeg"):
            _audit("list_download_jobs", "VALIDATION_ERROR", message="invalid outputFormat")
            return _err("VALIDATION_ERROR", "Invalid outputFormat", allowed=["svg", "png", "pdf", "jpeg"])

    if page is None:
        page = 1
    if pageSize is None:
        pageSize = 50
    if sortOrder is None:
        sortOrder = "desc"

    if not isinstance(page, int) or page < 1:
        _audit("list_download_jobs", "VALIDATION_ERROR", message="page must be int >= 1")
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 200:
        _audit("list_download_jobs", "VALIDATION_ERROR", message="pageSize out of range")
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 200")
    if sortBy is not None:
        if not isinstance(sortBy, str):
            _audit("list_download_jobs", "VALIDATION_ERROR", message="sortBy must be string")
            return _err("VALIDATION_ERROR", "sortBy must be a string")
        if sortBy not in ("created_at", "updated_at", "status", "started_at", "completed_at"):
            _audit("list_download_jobs", "VALIDATION_ERROR", message="invalid sortBy")
            return _err("VALIDATION_ERROR", "Invalid sortBy", allowed=["created_at", "updated_at", "status", "started_at", "completed_at"])
    if sortOrder not in ("asc", "desc"):
        _audit("list_download_jobs", "VALIDATION_ERROR", message="invalid sortOrder")
        return _err("VALIDATION_ERROR", "Invalid sortOrder", allowed=["asc", "desc"])

    jobs = _load("download_jobs.json")
    items = []
    for j in jobs:
        if diagramRequestId is not None and j.get("diagram_request_id") != diagramRequestId:
            continue
        if status is not None and j.get("status") != status:
            continue
        if outputFormat is not None and j.get("output_format") != outputFormat:
            continue
        items.append(j)

    if sortBy is None:
        sortBy = "created_at"
    reverse = (sortOrder == "desc")

    def _key(v):
        val = v.get(sortBy)
        return (val is None, val)

    try:
        items.sort(key=_key, reverse=reverse)
    except TypeError:
        items.sort(key=lambda x: (x.get(sortBy) is None, str(x.get(sortBy))), reverse=reverse)

    total = len(items)
    start_i = (page - 1) * pageSize
    end_i = start_i + pageSize
    page_items = items[start_i:end_i]
    has_more = end_i < total

    _audit("list_download_jobs", "OK")
    return {
        "data": page_items,
        "meta": {
            "page": page,
            "page_size": pageSize,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
            "sort_by": sortBy,
            "sort_order": sortOrder,
        },
    }

def get_caller_context(includeRateLimits=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0383000" if __import__("os").path.isdir("./environment_mix/0383000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(endpoint, status_code, credential_id=None, message=None):
        for fname in ("request_logs.json", "audit_logs.json", "usage_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                rows = _load(fname)
                latency_ms = int((datetime.datetime.utcnow() - start).total_seconds() * 1000)
                rows.append({
                    "id": f"req_{int(datetime.datetime.utcnow().timestamp()*1000)}_{os.getpid()}",
                    "endpoint": endpoint,
                    "credential_id": credential_id,
                    "status": status_code,
                    "message": message,
                    "latency_ms": latency_ms,
                    "created_at": _now_iso(),
                })
                _save(fname, rows)
                break

    if includeRateLimits is None:
        includeRateLimits = True
    if not isinstance(includeRateLimits, bool):
        _audit("get_caller_context", "VALIDATION_ERROR", message="includeRateLimits must be boolean")
        return _err("VALIDATION_ERROR", "includeRateLimits must be a boolean")

    # This service schema does not define credentials/accounts. Ambient auth is assumed.
    # Only refuse UNAUTHORIZED if there is an explicit credential system present and none are valid.
    # We'll look for common credential collections; if present and all are invalid/disabled -> UNAUTHORIZED.
    cred_files = ("credentials.json", "api_keys.json", "access_tokens.json", "users.json")
    found_cred_system = any(os.path.exists(os.path.join(_DB, f)) for f in cred_files)

    credential = None
    if found_cred_system:
        # best effort: find any active credential; if none, unauthorized
        for f in cred_files:
            if not os.path.exists(os.path.join(_DB, f)):
                continue
            rows = _load(f)
            for r in rows:
                if isinstance(r, dict) and (r.get("disabled") is True or r.get("revoked") is True):
                    continue
                # if there's an "active" field, require it; otherwise accept the row
                if "active" in r and r.get("active") is not True:
                    continue
                credential = r
                break
            if credential:
                break
        if not credential:
            _audit("get_caller_context", "UNAUTHORIZED", message="no valid credentials available")
            return _err("UNAUTHORIZED", "No valid credentials presented")

    context = {
        "data": {
            "authenticated": True,
            "caller": {
                "credential_id": credential.get("id") if isinstance(credential, dict) else None,
                "kind": "ambient" if not credential else "stored",
            },
            "scopes": ["read:diagram_requests", "read:download_jobs"],
            "server_time": _now_iso(),
        }
    }

    if includeRateLimits:
        # If request log exists, compute simple rolling window usage (last 60s)
        rl = {"available": False}
        for fname in ("request_logs.json", "audit_logs.json", "usage_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                rows = _load(fname)
                now = datetime.datetime.utcnow()
                window_s = 60
                used = 0
                for r in rows:
                    ts = r.get("created_at")
                    if not isinstance(ts, str):
                        continue
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", ""))
                    except Exception:
                        continue
                    if (now - dt).total_seconds() <= window_s:
                        used += 1
                rl = {
                    "available": True,
                    "window_seconds": window_s,
                    "used": used,
                    "remaining": None,
                    "limit": None,
                }
                break
        context["data"]["rate_limits"] = rl

    _audit("get_caller_context", "OK", credential_id=context["data"]["caller"]["credential_id"])
    return context
